window.AGREEMENTS = {"zh": [{"k": "h1", "t": "跨境就医个人信息及健康医疗资料传输协议"}, {"k": "p", "t": "请在签署前仔细阅读以下全部条款。本协议仅适用于本次跨境就医及本次明确列明的资料传输。"}, {"k": "h2", "t": "本次授权信息"}, {"k": "p", "t": "患者姓名：{{B:28}}"}, {"k": "p", "t": "代办人姓名及与患者关系（如适用）：{{B:28}}"}, {"k": "p", "t": "资料提供方：{{B:28}}"}, {"k": "p", "t": "接收医疗机构：{{B:28}}"}, {"k": "p", "t": "跨境路径：{{B:28}}"}, {"k": "p", "t": "本次诊疗目的：{{B:28}}"}, {"k": "p", "t": "授权有效期：自{{B:8}}年{{B:4}}月{{B:4}}日{{B:4}}时{{B:4}}分至{{B:8}}年{{B:4}}月{{B:4}}日{{B:4}}时{{B:4}}分"}, {"k": "h2", "t": "通用条款"}, {"k": "h3", "t": "第1条｜本次跨境医疗服务"}, {"k": "p", "t": "您正在申请跨境预约挂号、转诊、远程会诊、诊断、治疗、复诊、检查检验、处方核验、药物管理或医疗纪录回传服务。"}, {"k": "p", "t": "为使接收医疗机构了解您的身体状况并提供连续、安全的医疗服务，系统需要将本协议列明的身份资料和健康医疗资料，从本协议列明的资料提供方传输至本协议列明的接收医疗机构。"}, {"k": "p", "t": "本次授权仅适用于本次就诊申请，不构成对其他医院、其他就诊或未来医疗服务的长期授权。"}, {"k": "h3", "t": "第2条｜患者、代理者及代理资格"}, {"k": "p", "t": "本次资料所涉及的患者，是本协议“本次授权信息”部分列明的自然人。"}, {"k": "p", "t": "患者本人操作的，应完成实名身份核验；由子女、配偶、监护人、照顾者或其他代办人操作的，代办人应完成身份核验，并确认已经取得患者明确授权，或者依法具有代患者作出决定的资格。"}, {"k": "p", "t": "平台将保存授权关系、核验结果及操作记录。"}, {"k": "h3", "t": "第3条｜资料提供方及平台运营方"}, {"k": "p", "t": "本次资料提供方为本协议列明法定全称的医院、诊所或电子健康纪录系统运营机构。"}, {"k": "p", "t": "资料提供方应向患者提供其注册地址、医疗机构执业许可证信息、联系电话和电子邮箱。"}, {"k": "p", "t": "平台运营方如参与资料检索、身份匹配、格式转换、加密传输、临时缓存或访问日志管理，应同时向患者提供平台运营方的法定全称、注册地址、统一社会信用代码或商业登记资料、客服电话、电子邮箱及个人信息保护负责人联系方式。"}, {"k": "h3", "t": "第4条｜接收医疗机构"}, {"k": "p", "t": "本次接收方仅为本协议列明法定全称的医疗机构。"}, {"k": "p", "t": "接收医疗机构应向患者提供其注册地址、医疗机构登记或许可资料、联系电话、电子邮箱、接诊科室及负责此次诊疗的医护团队信息。"}, {"k": "p", "t": "未经患者重新授权，资料不得提供给本协议未列明的其他医院、诊所、养老机构、药房、保险公司、健康管理公司或商业机构。"}, {"k": "h3", "t": "第5条｜处理目的及禁止用途"}, {"k": "h2", "t": "接收医疗机构仅可为以下目的处理资料："}, {"k": "p", "t": "核实患者身份；"}, {"k": "p", "t": "完成预约、分诊和转诊；"}, {"k": "p", "t": "了解患者过敏史、药物不良反应、既往病史和当前用药；"}, {"k": "p", "t": "辅助医生作出诊断、治疗和复诊决定；"}, {"k": "p", "t": "避免重复检查、重复用药和存在冲突的处方；"}, {"k": "p", "t": "提供检验、影像、药事及护理服务；"}, {"k": "p", "t": "形成并向患者提供本次就诊记录。"}, {"k": "p", "t": "未经另行合法授权，不得将有关资料用于广告、直接营销、保险产品推介、商业画像、信用评估、与本次诊疗无关的人工智能训练、非必要医学研究或其他不相容目的。"}, {"k": "h3", "t": "第6条｜身份、预约及照护资料"}, {"k": "h2", "t": "本次可能传输的身份及就医安排资料仅包括："}, {"k": "p", "t": "患者姓名；"}, {"k": "p", "t": "性别；"}, {"k": "p", "t": "出生日期；"}, {"k": "p", "t": "证件类型及证件号码；"}, {"k": "p", "t": "国籍或地区；"}, {"k": "p", "t": "病历号及就诊号；"}, {"k": "p", "t": "手机号码及住址；"}, {"k": "p", "t": "紧急联系人；"}, {"k": "p", "t": "照顾者或代办人的身份及关系；"}, {"k": "p", "t": "接收医院；"}, {"k": "p", "t": "接诊科室及接诊医生；"}, {"k": "p", "t": "预约日期；"}, {"k": "p", "t": "转诊原因；"}, {"k": "p", "t": "初步症状及紧急程度；"}, {"k": "p", "t": "轮椅、陪诊、翻译、听力、视力或其他无障碍服务需要。"}, {"k": "p", "t": "系统必须逐项显示本次实际传输的项目。未被勾选的项目不得传输。"}, {"k": "h3", "t": "第7条｜敏感健康医疗资料"}, {"k": "h2", "t": "本次涉及的健康医疗敏感个人信息包括系统实际勾选的下列项目："}, {"k": "p", "t": "主诉及现病史；"}, {"k": "p", "t": "既往病史；"}, {"k": "p", "t": "手术史及住院史；"}, {"k": "p", "t": "家族病史；"}, {"k": "p", "t": "传染病史；"}, {"k": "p", "t": "过敏史；"}, {"k": "p", "t": "药物不良反应；"}, {"k": "p", "t": "当前及既往用药；"}, {"k": "p", "t": "诊断结果；"}, {"k": "p", "t": "处方；"}, {"k": "p", "t": "门诊病历及住院病历；"}, {"k": "p", "t": "出院小结；"}, {"k": "p", "t": "护理记录及医嘱；"}, {"k": "p", "t": "检验报告及病理报告；"}, {"k": "p", "t": "疫苗接种记录；"}, {"k": "p", "t": "血型；"}, {"k": "p", "t": "血压、血糖、血氧及心率；"}, {"k": "p", "t": "康复记录；"}, {"k": "p", "t": "X光、CT、MRI、超声、内窥镜等医学影像及相关报告。"}, {"k": "p", "t": "系统不得默认选择全部病历，只能选择本次诊疗确有必要的资料项目。"}, {"k": "h3", "t": "第8条｜传输方式及访问人员"}, {"k": "p", "t": "资料应通过经身份认证的加密接口或加密网页传输，不得通过普通电子邮件、个人即时通讯账号、公开网盘或未经批准的移动存储设备发送。"}, {"k": "h2", "t": "资料传输至接收医疗机构后，仅限以下直接参与本次诊疗的实名人员访问："}, {"k": "p", "t": "注册医生；"}, {"k": "p", "t": "护士；"}, {"k": "p", "t": "药师；"}, {"k": "p", "t": "检验人员；"}, {"k": "p", "t": "影像人员；"}, {"k": "p", "t": "康复人员；"}, {"k": "p", "t": "依法承担病历管理职责的授权人员。"}, {"k": "p", "t": "每次访问、下载、修改、打印或转发均应记录访问人员、访问时间、资料范围、操作终端和处理目的。"}, {"k": "h3", "t": "第9条｜访问期限、保存期限及删除"}, {"k": "p", "t": "接收医疗机构的在线查阅权限，原则上自预约日期前7日开始，并在本次就诊结束后30日自动关闭。"}, {"k": "p", "t": "远程会诊或紧急转诊可在患者授权后即时开放。"}, {"k": "p", "t": "需要继续复诊或延长查阅期限的，应重新告知患者并取得授权。"}, {"k": "p", "t": "为跨境传输产生的临时文件、缓存和中间副本，应在用途完成后30日内删除。"}, {"k": "p", "t": "接收医疗机构依法形成的本地病历，按照接收地医疗记录保存规则保存，不因患者撤回跨境传输同意而当然删除。"}, {"k": "h3", "t": "第10条｜安全措施、受托处理及再提供"}, {"k": "h2", "t": "资料提供方、平台运营方和接收医疗机构应采取以下安全措施："}, {"k": "p", "t": "传输加密；"}, {"k": "p", "t": "存储加密；"}, {"k": "p", "t": "双重身份认证；"}, {"k": "p", "t": "最小权限控制；"}, {"k": "p", "t": "访问审批；"}, {"k": "p", "t": "操作日志；"}, {"k": "p", "t": "安全审计；"}, {"k": "p", "t": "异常访问警报；"}, {"k": "p", "t": "备份保护；"}, {"k": "p", "t": "安全事件响应。"}, {"k": "p", "t": "接收方仅可将必要资料提供给为本次诊疗提供检验、影像、药事、康复或系统维护服务的受托方，并应通过书面合同限制受托方的处理目的、资料范围、保存期限和转委托行为。"}, {"k": "p", "t": "未经新的合法依据，不得将资料继续提供给其他司法管辖区或其他机构。"}, {"k": "h3", "t": "第11条｜患者权利、撤回及投诉"}, {"k": "p", "t": "患者可以查看资料提供方、接收医疗机构、资料清单、授权期限及访问记录，并可以停止尚未发生的后续传输。"}, {"k": "p", "t": "患者有权申请查阅、更正或补充不准确的身份资料和医疗资料，并可就未经授权的访问、超范围处理或资料泄露提出投诉。"}, {"k": "p", "t": "患者撤回同意，不影响撤回前已经完成的合法处理，也不要求医疗机构删除依法必须保存的病历。"}, {"k": "h3", "t": "第12条｜资料安全事件"}, {"k": "h2", "t": "发生或可能发生资料泄露、篡改、丢失、非法利用或未经授权访问时，相关机构应立即："}, {"k": "p", "t": "停止风险来源；"}, {"k": "p", "t": "限制相关账号和访问权限；"}, {"k": "p", "t": "保存有关证据；"}, {"k": "p", "t": "评估事件影响；"}, {"k": "p", "t": "采取补救措施。"}, {"k": "h2", "t": "依法需要通知患者时，通知应说明："}, {"k": "p", "t": "事件涉及的资料种类；"}, {"k": "p", "t": "事件发生原因；"}, {"k": "p", "t": "可能产生的影响；"}, {"k": "p", "t": "已经采取的补救措施；"}, {"k": "p", "t": "患者可以采取的保护措施；"}, {"k": "p", "t": "负责处理事件的联系人及联系方式。"}, {"k": "p", "t": "相关机构还应按照各自属地适用的法律和监管要求向主管机关报告。"}, {"k": "h3", "t": "第13条｜紧急情况下的预先授权与必要资料访问"}, {"k": "p", "t": "本人自愿、明确并单独同意：当发生危及本人生命或身体健康的紧急情况，且本人因昏迷、认知障碍、严重沟通障碍或其他原因无法及时表达意愿时，接诊医院可在保护本人生命健康所必需的最小范围内，直接调取并使用以下信息："}, {"k": "p", "t": "已知过敏原及过敏反应；"}, {"k": "p", "t": "严重药物不良反应；"}, {"k": "p", "t": "当前关键用药；"}, {"k": "p", "t": "重要既往病史；"}, {"k": "p", "t": "重大手术史；"}, {"k": "p", "t": "植入式医疗器械；"}, {"k": "p", "t": "传染病风险；"}, {"k": "p", "t": "血型；"}, {"k": "p", "t": "由接诊医生书面判断为紧急救治必须知晓的其他信息。"}, {"k": "p", "t": "该权限不得用于常规诊疗、营销、研究、保险评估或其他非紧急目的。"}, {"k": "p", "t": "每次紧急访问均须记录访问人员、访问时间、访问理由、资料范围和处置结果。"}, {"k": "p", "t": "紧急情况消除后，医院应尽快通知本人或依法有权代为决定的人。"}, {"k": "p", "t": "本授权可随时撤回，但撤回不影响撤回前已经依法完成的紧急处理。"}, {"k": "h2", "t": "路径一｜中国内地 → 香港"}, {"k": "p", "t": "仅在本次跨境路径为“中国内地 → 香港”时适用。"}, {"k": "h3", "t": "第14条｜适用制度与跨境机制"}, {"k": "p", "t": "本次资料提供方位于中国内地，接收方位于香港特别行政区。"}, {"k": "p", "t": "资料提供方应依照《中华人民共和国个人信息保护法》，履行个人信息出境告知、敏感个人信息告知、个人信息保护影响评估及适用的跨境个人信息传输程序。"}, {"k": "p", "t": "接收方在香港处理资料时，应遵守香港《个人资料（私隐）条例》及适用的保障资料原则。"}, {"k": "p", "t": "双方符合适用条件时，可采用粤港澳大湾区内地与香港个人信息跨境流动标准合同。"}, {"k": "h3", "t": "第15条｜接收后的访问安排"}, {"k": "p", "t": "香港接收医院只能允许参与本次诊疗的实名医护人员访问资料。"}, {"k": "h2", "t": "每次访问后，系统应向患者预留的手机号码或电子邮箱发送通知，载明："}, {"k": "p", "t": "医院名称；"}, {"k": "p", "t": "访问时间；"}, {"k": "p", "t": "资料类别；"}, {"k": "p", "t": "访问人员所属科室。"}, {"k": "h3", "t": "第16条｜法律差异提示"}, {"k": "p", "t": "香港与中国内地在个人资料术语、监管机关、投诉程序和医疗记录制度方面存在差异。"}, {"k": "p", "t": "资料进入香港后，由香港接收医院形成的本地诊疗纪录，将按照香港适用的法律及医疗记录管理规则处理。"}, {"k": "h3", "t": "第17条｜最终单独同意"}, {"k": "p", "t": "本人确认已阅读并理解本协议全部条款，并单独同意将本协议逐项列明的个人信息及健康医疗敏感个人信息，从本协议列明的中国内地医疗机构传输至本协议列明的香港医疗机构，仅用于本次跨境就医。"}, {"k": "h2", "t": "路径二｜中国内地 → 澳门"}, {"k": "p", "t": "仅在本次跨境路径为“中国内地 → 澳门”时适用。"}, {"k": "h3", "t": "第14条｜适用制度与跨境机制"}, {"k": "p", "t": "本次资料提供方位于中国内地，接收方位于澳门特别行政区。"}, {"k": "p", "t": "资料提供方应依照《中华人民共和国个人信息保护法》，履行个人信息处理告知、敏感个人信息处理、个人信息保护影响评估及适用的数据出境程序。"}, {"k": "p", "t": "澳门接收医疗机构作为负责处理个人资料的实体，应遵守澳门第8/2005号法律《个人资料保护法》。"}, {"k": "p", "t": "符合适用条件时，双方可采用粤港澳大湾区内地与澳门个人信息跨境流动标准合同。"}, {"k": "h3", "t": "第15条｜澳门接收方合规状态"}, {"k": "h2", "t": "澳门接收医疗机构应向患者说明："}, {"k": "p", "t": "已签署的标准合同名称；"}, {"k": "p", "t": "合同生效日期；"}, {"k": "p", "t": "备案提交日期；"}, {"k": "p", "t": "备案接收机关；"}, {"k": "p", "t": "当前备案状态；"}, {"k": "p", "t": "依法适用的自动化处理通知、敏感资料处理许可或其他程序的完成状态。"}, {"k": "p", "t": "在依法需要事先许可，而有关许可尚未作出前，不得启动资料传输。"}, {"k": "h3", "t": "第16条｜法律差异提示"}, {"k": "p", "t": "澳门法律将健康资料列为敏感资料。"}, {"k": "p", "t": "澳门与中国内地在主管机关、敏感资料处理条件、通知或许可程序以及资料当事人权利等方面存在差异。"}, {"k": "h3", "t": "第17条｜最终单独同意"}, {"k": "p", "t": "本人确认已阅读并理解本协议全部条款，并自由、具体、知情且明确地同意将本协议列明的个人信息及健康医疗敏感个人信息，从本协议列明的中国内地医疗机构传输至本协议列明的澳门医疗机构，仅用于本次跨境就医。"}, {"k": "h2", "t": "路径三｜香港 → 澳门"}, {"k": "p", "t": "仅在本次跨境路径为“香港 → 澳门”时适用。"}, {"k": "h3", "t": "第14条｜适用制度"}, {"k": "p", "t": "本次资料提供方为香港的资料使用者，接收方为澳门负责处理个人资料的实体。"}, {"k": "p", "t": "香港资料提供方应遵守香港《个人资料（私隐）条例》及适用的保障资料原则；澳门接收方应遵守澳门第8/2005号法律《个人资料保护法》。"}, {"k": "p", "t": "本路径不直接适用内地与香港或内地与澳门的大湾区个人信息跨境流动标准合同。"}, {"k": "h2", "t": "双方应以书面跨境资料处理合同明确："}, {"k": "p", "t": "处理目的；"}, {"k": "p", "t": "资料范围；"}, {"k": "p", "t": "安全措施；"}, {"k": "p", "t": "资料当事人权利响应机制；"}, {"k": "p", "t": "保存期限；"}, {"k": "p", "t": "再次转移限制；"}, {"k": "p", "t": "资料安全事件的处理责任。"}, {"k": "h3", "t": "第15条｜新用途判断"}, {"k": "p", "t": "资料提供方应明确说明本次资料转移是否属于原收集目的，或者是否属于与原收集目的直接相关的用途。"}, {"k": "p", "t": "如本次转移属于新的诊疗用途，香港资料提供方应在传输前取得患者明确、自愿且知情的订明同意。"}, {"k": "h3", "t": "第16条｜澳门程序状态"}, {"k": "p", "t": "澳门接收医疗机构应向患者说明本次敏感健康资料处理所适用的登记、通知或许可状态。"}, {"k": "p", "t": "依法需要事先许可而尚未取得许可的，不得开放资料访问。"}, {"k": "h3", "t": "第17条｜最终同意"}, {"k": "p", "t": "本人明确、自愿地同意将本协议逐项列明的个人资料及健康医疗敏感资料，从本协议列明的香港资料提供方传输至本协议列明的澳门医疗机构，仅用于本次跨境就医。"}, {"k": "h2", "t": "路径四｜澳门 → 香港"}, {"k": "p", "t": "仅在本次跨境路径为“澳门 → 香港”时适用。"}, {"k": "h3", "t": "第14条｜适用制度"}, {"k": "p", "t": "本次资料提供方为澳门负责处理个人资料的实体，接收方为香港医疗机构。"}, {"k": "p", "t": "澳门资料提供方应遵守澳门第8/2005号法律《个人资料保护法》，并根据该法律第19条、第20条及其他适用规定，确定向澳门以外地区转移个人资料的法律依据和适用程序。"}, {"k": "p", "t": "香港接收方应遵守香港《个人资料（私隐）条例》及适用的保障资料原则。"}, {"k": "h3", "t": "第15条｜澳门转出程序"}, {"k": "h2", "t": "澳门资料提供方应向患者说明："}, {"k": "p", "t": "本次转移适用澳门第8/2005号法律第19条或第20条的具体路径；"}, {"k": "p", "t": "通知提交日期；"}, {"k": "p", "t": "许可申请日期；"}, {"k": "p", "t": "主管机关编号；"}, {"k": "p", "t": "当前程序状态。"}, {"k": "p", "t": "依法需要事先取得许可的，在许可作出前不得传输资料。"}, {"k": "h3", "t": "第16条｜香港接收后的限制"}, {"k": "p", "t": "香港接收医院只能将资料用于本次诊疗，不得将资料用于直接促销或其他未经授权的新目的。"}, {"k": "p", "t": "需要将资料再次转移至香港以外的地区或机构时，应重新进行评估、履行告知义务并取得适用的授权或同意。"}, {"k": "h3", "t": "第17条｜最终同意"}, {"k": "p", "t": "本人自由、具体、知情且明确地同意将本协议列明的个人资料及健康医疗敏感资料，从本协议列明的澳门医疗机构传输至本协议列明的香港医疗机构，仅用于本次跨境就医。"}, {"k": "h2", "t": "路径五｜香港 → 中国内地"}, {"k": "p", "t": "仅在本次跨境路径为“香港 → 中国内地”时适用。"}, {"k": "h3", "t": "第14条｜适用制度与标准合同"}, {"k": "p", "t": "本次资料提供方为香港的资料使用者，接收方为中国内地医疗机构。"}, {"k": "p", "t": "香港资料提供方应遵守香港《个人资料（私隐）条例》及适用的保障资料原则；中国内地接收医院应按照《中华人民共和国个人信息保护法》处理资料。"}, {"k": "p", "t": "双方符合粤港澳大湾区内地与香港个人信息跨境流动标准合同适用条件时，应在标准合同生效并完成规定程序后开展资料传输。"}, {"k": "h3", "t": "第15条｜接收医院访问规则"}, {"k": "p", "t": "中国内地接收医院只能在患者本次就诊、会诊或复诊期间，允许实名注册并直接参与本次诊疗的医护人员访问资料。"}, {"k": "h2", "t": "每次访问后，系统应向患者发送通知，并列明："}, {"k": "p", "t": "接收医院；"}, {"k": "p", "t": "访问时间；"}, {"k": "p", "t": "访问资料的类别；"}, {"k": "p", "t": "访问人员所属科室。"}, {"k": "h3", "t": "第16条｜内地接收方的禁止行为"}, {"k": "h2", "t": "中国内地接收医院不得超出本协议列明的目的和资料种类处理相关资料，不得将资料用于："}, {"k": "p", "t": "药品广告；"}, {"k": "p", "t": "保险营销；"}, {"k": "p", "t": "商业画像；"}, {"k": "p", "t": "与本次诊疗无关的人工智能训练；"}, {"k": "p", "t": "其他与本次诊疗目的不相容的用途。"}, {"k": "p", "t": "处理目的、处理方式、资料种类或保存期限发生实质变化时，应重新进行个人信息保护影响评估，并重新告知患者及取得适用的同意。"}, {"k": "h3", "t": "第17条｜最终同意"}, {"k": "p", "t": "本人明确、自愿地同意将本协议列明的个人资料及健康医疗敏感资料，从本协议列明的香港资料提供方传输至本协议列明的中国内地医疗机构，仅用于本次跨境就医。"}, {"k": "h2", "t": "路径六｜澳门 → 中国内地"}, {"k": "p", "t": "仅在本次跨境路径为“澳门 → 中国内地”时适用。"}, {"k": "h3", "t": "第14条｜适用制度与标准合同"}, {"k": "p", "t": "本次资料提供方为澳门负责处理个人资料的实体，接收方为中国内地医疗机构。"}, {"k": "p", "t": "澳门资料提供方应遵守澳门第8/2005号法律《个人资料保护法》；中国内地接收医院应遵守《中华人民共和国个人信息保护法》。"}, {"k": "p", "t": "符合适用条件时，双方可采用粤港澳大湾区内地与澳门个人信息跨境流动标准合同。"}, {"k": "h3", "t": "第15条｜合同及备案状态"}, {"k": "h2", "t": "资料提供方和接收方应向患者说明："}, {"k": "p", "t": "双方签署的内地与澳门大湾区标准合同名称；"}, {"k": "p", "t": "合同生效日期；"}, {"k": "p", "t": "备案提交日期；"}, {"k": "p", "t": "备案接收机关；"}, {"k": "p", "t": "当前备案状态。"}, {"k": "p", "t": "程序尚未完成、合同已经失效或传输资料超出适用范围时，不得启动资料传输。"}, {"k": "h3", "t": "第16条｜澳门转出及内地接收限制"}, {"k": "p", "t": "澳门资料提供方应完成适用的跨境转移程序。"}, {"k": "p", "t": "中国内地接收医院只能按照本协议及适用的标准合同所列明的目的、方式和资料类别处理有关信息。"}, {"k": "p", "t": "处理目的、资料范围、处理方式或保存期限发生变化时，双方应重新评估，并根据实际情况补充或重新订立协议，履行相应的告知、同意及其他适用程序。"}, {"k": "h3", "t": "第17条｜最终同意"}, {"k": "p", "t": "本人自由、具体、知情且明确地同意将本协议列明的个人资料及健康医疗敏感资料，从本协议列明的澳门医疗机构传输至本协议列明的中国内地医疗机构，仅用于本次跨境就医。"}, {"k": "h2", "t": "签署确认"}, {"k": "h2", "t": "一、协议阅读确认"}, {"k": "p", "t": "{{C}} 我已逐条阅读并理解本协议。"}, {"k": "h2", "t": "二、跨境传输单独同意"}, {"k": "p", "t": "{{C}} 我单独同意本次个人信息跨境传输。"}, {"k": "h2", "t": "三、敏感健康医疗资料单独同意"}, {"k": "p", "t": "{{C}} 我另行同意传输本协议列明的健康医疗敏感个人信息。"}, {"k": "h2", "t": "四、紧急访问单独同意"}, {"k": "p", "t": "{{C}} 我单独同意在本协议所述紧急情况下，由接诊医院按最小必要范围访问救治所必需的健康医疗资料。"}, {"k": "h2", "t": "五、签署资格确认"}, {"k": "p", "t": "{{C}} 我是患者本人。"}, {"k": "p", "t": "{{C}} 我不是患者本人，但已取得患者明确授权。"}, {"k": "p", "t": "{{C}} 我依法具有代患者作出相关决定的资格。"}, {"k": "p", "t": "代办人或法定代理人与患者的关系：{{B:28}}"}, {"k": "p", "t": "代理权限或法律依据：{{B:28}}"}, {"k": "h2", "t": "六、实际适用的跨境路径"}, {"k": "h2", "t": "请只勾选一项："}, {"k": "h2", "t": "{{C}} 中国内地 → 香港"}, {"k": "h2", "t": "{{C}} 中国内地 → 澳门"}, {"k": "h2", "t": "{{C}} 香港 → 澳门"}, {"k": "h2", "t": "{{C}} 澳门 → 香港"}, {"k": "h2", "t": "{{C}} 香港 → 中国内地"}, {"k": "h2", "t": "{{C}} 澳门 → 中国内地"}, {"k": "h2", "t": "七、签名"}, {"k": "p", "t": "患者签名：{{B:28}}"}, {"k": "p", "t": "法定代理人或获授权代办人签名（如适用）：{{B:28}}"}, {"k": "p", "t": "签署日期：{{B:8}}年{{B:4}}月{{B:4}}日"}, {"k": "p", "t": "联系电话：{{B:28}}"}, {"k": "p", "t": "电子邮箱（如有）：{{B:28}}"}, {"k": "p", "t": "重要提示：本协议中的六组路径特别条款属于备选条款。实际签署时，应只保留或启用与本次跨境路径对应的一组第14条至第17条，不应要求患者同时同意六条不同路径。1"}], "en": [{"k": "h1", "t": "Cross-boundary Healthcare Personal and Health Information Transfer Agreement"}, {"k": "p", "t": "Please read all provisions carefully before signing. This Agreement applies only to the current episode of cross-boundary care and the information transfer expressly identified for that episode."}, {"k": "h2", "t": "Authorization Details"}, {"k": "p", "t": "Patient name: {{B:28}}"}, {"k": "p", "t": "Representative and relationship to the patient, if applicable: {{B:28}}"}, {"k": "p", "t": "Transferor: {{B:28}}"}, {"k": "p", "t": "Recipient medical institution: {{B:28}}"}, {"k": "p", "t": "Cross-boundary route: {{B:28}}"}, {"k": "p", "t": "Purpose of care: {{B:28}}"}, {"k": "p", "t": "Authorization period: from {{B:4}}/{{B:4}}/{{B:8}} {{B:4}}:{{B:4}} to {{B:4}}/{{B:4}}/{{B:8}} {{B:4}}:{{B:4}}"}, {"k": "h2", "t": "General Provisions"}, {"k": "h3", "t": "Clause 1 | Current Cross-boundary Healthcare Service"}, {"k": "p", "t": "You are applying for a cross-boundary appointment, referral, teleconsultation, diagnosis, treatment, follow-up, examination, laboratory test, prescription verification, medication management or medical-record return service. To enable the recipient medical institution to understand your condition and provide safe and continuous care, the identity and health information listed on this page will be transferred from the identified provider to the identified recipient. This authorization applies only to the current episode of care and is not a continuing authorization for another institution, visit or future service."}, {"k": "h3", "t": "Clause 2 | Patient, Representative and Authority to Act"}, {"k": "p", "t": "The patient concerned is the natural person whose name, date of birth, document type and last four digits of the document number are displayed on this page. A patient acting personally must complete identity verification. A child, spouse, guardian, caregiver or representative acting for the patient must verify their identity and confirm valid authorization or lawful representative authority. The platform will retain records of the authority, verification result and relevant operations."}, {"k": "h3", "t": "Clause 3 | Transferor and Platform Operator"}, {"k": "p", "t": "The transferor is the hospital, clinic or electronic-health-record operator whose full legal name, registered address, medical-institution licence information, telephone number and email address are displayed on this page. If the platform operator participates in retrieval, identity matching, format conversion, encrypted transmission, temporary caching or access-log management, its full legal identity, registered address, registration particulars, customer-service number, email address and data-protection contact must also be displayed."}, {"k": "h3", "t": "Clause 4 | Recipient Medical Institution"}, {"k": "p", "t": "The recipient is limited to the medical institution identified by its full legal name on this page. Its registered address, registration or licence particulars, telephone number, email address, receiving department and responsible care team must also be displayed. Without renewed authorization, the information must not be disclosed to another hospital, clinic, elderly-care institution, pharmacy, insurer, health-management company or commercial organization not identified on this page."}, {"k": "h3", "t": "Clause 5 | Purposes of Processing and Prohibited Uses"}, {"k": "p", "t": "The recipient may process the information only to verify identity, complete appointments, triage and referrals, review allergies, adverse drug reactions, medical history and medication, support diagnosis, treatment and follow-up, avoid duplicate examinations or conflicting medication, provide laboratory, imaging, pharmacy and nursing services, and create the current clinical record. Without a separate lawful authorization, the information must not be used for advertising, direct marketing, insurance promotion, commercial profiling, credit assessment, unrelated AI training, unnecessary research or another incompatible purpose."}, {"k": "h3", "t": "Clause 6 | Identity, Appointment and Care Information"}, {"k": "p", "t": "Identity and care-arrangement information is limited to the patient’s name, sex, date of birth, identity-document particulars, nationality or region, medical-record and visit numbers, mobile number, address, emergency contact, caregiver or representative details, recipient hospital, department, doctor, appointment date, referral reason, preliminary symptoms, urgency and wheelchair, accompaniment, interpretation, hearing, visual or other accessibility requirements. The system must list every item selected for the current transfer. Unselected items must not be transferred."}, {"k": "h3", "t": "Clause 7 | Sensitive Health and Medical Information"}, {"k": "p", "t": "Sensitive health information is limited to the items actually selected by the system, including presenting complaints, current and previous illnesses, surgery and hospitalization history, family and infectious-disease history, allergies, adverse drug reactions, current and previous medication, diagnoses, prescriptions, outpatient and inpatient records, discharge summaries, nursing records, medical orders, laboratory and pathology reports, vaccination records, blood group, blood pressure, blood glucose, oxygen saturation, heart rate, rehabilitation records and medical images and reports, including X-ray, CT, MRI, ultrasound and endoscopy. The system must not select the complete record by default."}, {"k": "h3", "t": "Clause 8 | Transfer Method and Authorized Personnel"}, {"k": "p", "t": "Information must be transmitted through an authenticated encrypted interface or webpage and not through ordinary email, personal messaging accounts, public cloud drives or unauthorized removable media. Access is restricted to verified doctors, nurses, pharmacists, laboratory, imaging and rehabilitation personnel directly involved in the current care and authorized staff responsible for clinical-record management. Every access, download, amendment, printing or transmission must be logged."}, {"k": "h3", "t": "Clause 9 | Access Period, Retention Period and Deletion"}, {"k": "p", "t": "Online access ordinarily begins seven days before the appointment and closes automatically 30 days after the current episode of care. Teleconsultation or emergency referral access may begin immediately after authorization. Continued follow-up or an extension requires renewed notice and authorization. Temporary files, caches and intermediate copies created for transfer must be deleted within 30 days after completion of their purpose. Clinical records lawfully created by the recipient will be retained under applicable medical-record rules and are not automatically deleted when consent to future transfer is withdrawn."}, {"k": "h3", "t": "Clause 10 | Security Measures, Entrusted Processing and Further Disclosure"}, {"k": "p", "t": "The transferor, platform operator and recipient must apply encryption in transit and at rest, two-factor authentication, least-privilege access, access approval, logging, audit, unusual-access alerts, backup protection and incident-response measures. The recipient may disclose only necessary information to contracted laboratory, imaging, pharmacy, rehabilitation or system-maintenance processors and must restrict their purposes, scope, retention and subcontracting by written contract. No onward cross-jurisdictional disclosure is permitted without a new lawful basis."}, {"k": "h3", "t": "Clause 11 | Patient Rights, Withdrawal and Complaints"}, {"k": "p", "t": "The patient may use “Cross-boundary Care – Authorization Management” to view the transferor, recipient, data list, authorization period and access history and may stop future transfers that have not yet occurred. The patient may request access, correction or supplementation and complain about unauthorized access, excessive processing or a data breach. Withdrawal does not invalidate prior lawful processing or require deletion of clinical records that must be retained by law."}, {"k": "h3", "t": "Clause 12 | Personal Data Security Incidents"}, {"k": "p", "t": "If information is or may be leaked, altered, lost, unlawfully used or accessed without authorization, the relevant institutions must contain the source, restrict accounts and access, preserve evidence, assess the impact and take remedial action. Where notification is required, it must identify the information involved, cause, possible effects, remedial action, protective steps available to the patient and an incident contact. Regulatory reports must be made under applicable local requirements."}, {"k": "h3", "t": "Clause 13 | Advance Authorization for Necessary Access in an Emergency"}, {"k": "h3", "t": "Clause 13 | Advance Authorization for Necessary Access in an Emergency"}, {"k": "h2", "t": "Route One | Mainland China → Hong Kong"}, {"k": "p", "t": "Applies only where the current cross-boundary route is “Mainland China → Hong Kong”."}, {"k": "h3", "t": "Clause 14 | Applicable Framework and Cross-boundary Mechanism"}, {"k": "p", "t": "I voluntarily, expressly and separately agree that, where an emergency threatens my life or physical health and I cannot promptly express my wishes because of unconsciousness, cognitive impairment, a serious communication barrier or another cause, the treating hospital may directly retrieve and use, to the minimum extent necessary to protect my life or health: known allergens and allergic reactions; serious adverse drug reactions; current critical medication; significant medical and major surgical history; implanted medical devices; communicable-disease risks; blood group; and other information that the treating physician documents as essential for emergency care. This authority must not be used for routine care, marketing, research, insurance assessment or another non-emergency purpose. Each emergency access must record the accessor, time, reason, data scope and outcome. After the emergency ends, the hospital must notify me, or a person lawfully authorized to decide for me, as soon as practicable. I may withdraw this authorization at any time, without affecting emergency processing lawfully completed before withdrawal."}, {"k": "h3", "t": "Clause 15 | Access Arrangements after Receipt"}, {"k": "h2", "t": "Agreement 1 | Mainland China → Hong Kong"}, {"k": "h3", "t": "Clause 16 | Notice of Legal Differences"}, {"k": "p", "t": "The transferor is located in Mainland China and the recipient in Hong Kong. The transferor must fulfil the applicable notice, sensitive-information notice, impact-assessment and cross-boundary requirements under the Personal Information Protection Law. The recipient must comply with the Hong Kong Personal Data (Privacy) Ordinance and applicable Data Protection Principles. Where eligible, the parties may use the Mainland–Hong Kong GBA Standard Contract."}, {"k": "h3", "t": "Clause 17 | Final Separate Consent"}, {"k": "p", "t": "The Hong Kong recipient may allow access only to verified healthcare professionals involved in the current care. After each access, the patient will be notified of the hospital, access time, information categories and department."}, {"k": "h2", "t": "Route Two | Mainland China → Macao"}, {"k": "p", "t": "Applies only where the current cross-boundary route is “Mainland China → Macao”."}, {"k": "h3", "t": "Clause 14 | Applicable Framework and Cross-boundary Mechanism"}, {"k": "p", "t": "Hong Kong and Mainland China use different terminology, regulators, complaint procedures and medical-record systems. Clinical records created by the Hong Kong recipient will be managed under applicable Hong Kong requirements."}, {"k": "h3", "t": "Clause 15 | Compliance Status of the Macao Recipient"}, {"k": "p", "t": "I confirm that I have read all provisions and separately consent to the transfer of the listed personal and sensitive health information from the identified Mainland medical institution to the identified Hong Kong medical institution solely for the current episode of cross-boundary care."}, {"k": "h3", "t": "Clause 16 | Notice of Legal Differences"}, {"k": "h2", "t": "Agreement 2 | Mainland China → Macao"}, {"k": "h3", "t": "Clause 17 | Final Separate Consent"}, {"k": "p", "t": "The transferor is located in Mainland China and the recipient in Macao. The transferor must fulfil notice, sensitive-information, impact-assessment and applicable outbound-transfer requirements under the Personal Information Protection Law. The Macao medical institution, as the controller, must comply with Macao Law No. 8/2005. Where eligible, the parties may use the Mainland–Macao GBA Standard Contract."}, {"k": "h2", "t": "Route Three | Hong Kong → Macao"}, {"k": "p", "t": "Applies only where the current cross-boundary route is “Hong Kong → Macao”."}, {"k": "h3", "t": "Clause 14 | Applicable Framework"}, {"k": "p", "t": "The system must display the Standard Contract, effective date, filing date and filing status. If notification, sensitive-data authorization or another procedure is required, its status must also be displayed. No transfer may begin before a required prior authorization is obtained."}, {"k": "h3", "t": "Clause 15 | Assessment of a New Purpose"}, {"k": "p", "t": "Macao law treats health data as sensitive data. Macao and Mainland China differ in regulators, conditions for sensitive-data processing, notification or authorization procedures and data-subject rights."}, {"k": "h3", "t": "Clause 16 | Status of Macao Procedures"}, {"k": "p", "t": "I freely, specifically, knowingly and expressly consent to the transfer of the listed personal and sensitive health information from the identified Mainland medical institution to the identified Macao medical institution solely for the current care."}, {"k": "h3", "t": "Clause 17 | Final Consent"}, {"k": "h2", "t": "Agreement 3 | Hong Kong → Macao"}, {"k": "h2", "t": "Route Four | Macao → Hong Kong"}, {"k": "p", "t": "Applies only where the current cross-boundary route is “Macao → Hong Kong”."}, {"k": "h3", "t": "Clause 14 | Applicable Framework"}, {"k": "p", "t": "The transferor is a Hong Kong data user and the recipient a Macao controller. The transferor must comply with the Hong Kong Personal Data (Privacy) Ordinance and the recipient with Macao Law No. 8/2005. The Mainland–Hong Kong and Mainland–Macao GBA Standard Contracts do not directly govern this route. The parties must use a written cross-boundary agreement covering purposes, scope, security, rights, retention and onward-transfer restrictions."}, {"k": "h3", "t": "Clause 15 | Macao Outbound-transfer Procedure"}, {"k": "p", "t": "The system must state whether the transfer falls within the original collection purpose or a directly related purpose. If it constitutes a new clinical purpose, the Hong Kong transferor must obtain the patient’s express, voluntary and informed prescribed consent before transfer."}, {"k": "h3", "t": "Clause 16 | Restrictions after Receipt in Hong Kong"}, {"k": "p", "t": "The system must display the registration, notification or authorization status applicable to the Macao recipient’s processing of sensitive health data. Access must not begin while a required prior authorization remains outstanding."}, {"k": "h3", "t": "Clause 17 | Final Consent"}, {"k": "p", "t": "I expressly and voluntarily consent to the transfer of the listed personal and sensitive health data from the Hong Kong transferor to the identified Macao medical institution solely for the current care."}, {"k": "h2", "t": "Route Five | Hong Kong → Mainland China"}, {"k": "p", "t": "Applies only where the current cross-boundary route is “Hong Kong → Mainland China”."}, {"k": "h3", "t": "Clause 14 | Applicable Framework and Standard Contract"}, {"k": "p", "t": "The transferor is a Macao controller and the recipient a Hong Kong medical institution. The Macao controller must comply with Law No. 8/2005 and determine the lawful basis and procedure for an external transfer under Articles 19 and 20 and other applicable provisions. The Hong Kong recipient must comply with the Personal Data (Privacy) Ordinance."}, {"k": "h3", "t": "Clause 15 | Access Rules of the Recipient Hospital"}, {"k": "p", "t": "The system must identify whether Article 19 or Article 20 applies and display the notification date, authorization-application date, authority reference number and current status. Where prior authorization is required, no transfer may occur before it is obtained."}, {"k": "h3", "t": "Clause 16 | Prohibited Conduct of the Mainland Recipient"}, {"k": "p", "t": "The Hong Kong recipient may use the information only for the current care and must not use it for direct marketing or an unauthorized new purpose. Any onward transfer outside Hong Kong requires renewed assessment, notice and applicable authorization."}, {"k": "h3", "t": "Clause 17 | Final Consent"}, {"k": "p", "t": "I freely, specifically, knowingly and expressly consent to the transfer of the listed personal and sensitive health data from the identified Macao medical institution to the identified Hong Kong medical institution solely for the current care."}, {"k": "h2", "t": "Route Six | Macao → Mainland China"}, {"k": "p", "t": "Applies only where the current cross-boundary route is “Macao → Mainland China”."}, {"k": "h3", "t": "Clause 14 | Applicable Framework and Standard Contract"}, {"k": "p", "t": "The transferor is a Hong Kong data user and the recipient a Mainland medical institution. The transferor must comply with the Hong Kong Personal Data (Privacy) Ordinance, and the Mainland hospital must process the information under the Personal Information Protection Law. Where eligible, transfer must occur only after the GBA Standard Contract takes effect and the required filing is completed."}, {"k": "h3", "t": "Clause 15 | Contract and Filing Status"}, {"k": "p", "t": "The Mainland recipient may permit access only during the current appointment, consultation or follow-up and only to verified healthcare professionals directly involved in the care. The patient must be notified after each access."}, {"k": "h3", "t": "Clause 16 | Macao Outbound-transfer and Mainland Receipt Restrictions"}, {"k": "p", "t": "The Mainland recipient must not exceed the stated purposes and data categories or use the information for pharmaceutical advertising, insurance marketing, commercial profiling or unrelated AI training. A material change requires a renewed impact assessment, notice and applicable consent."}, {"k": "h3", "t": "Clause 17 | Final Consent"}, {"k": "p", "t": "I expressly and voluntarily consent to the transfer of the listed personal and sensitive health data from the identified Hong Kong transferor to the identified Mainland medical institution solely for the current care."}, {"k": "h2", "t": "Signature Confirmation"}, {"k": "p", "t": "1. Confirmation of Reading"}, {"k": "p", "t": "{{C}} I have read and understood every provision of this Agreement."}, {"k": "p", "t": "2. Separate Consent to Cross-boundary Transfer"}, {"k": "p", "t": "{{C}} I separately consent to this cross-boundary transfer of personal information."}, {"k": "p", "t": "3. Separate Consent to Sensitive Health and Medical Information"}, {"k": "p", "t": "{{C}} I separately consent to the transfer of the sensitive health and medical information identified in this Agreement."}, {"k": "p", "t": "4. Separate Consent to Emergency Access"}, {"k": "p", "t": "{{C}} I separately consent to minimum-necessary access by the treating hospital to health and medical information essential for emergency care in the circumstances described in this Agreement."}, {"k": "p", "t": "5. Confirmation of Signing Authority"}, {"k": "p", "t": "{{C}} I am the patient."}, {"k": "p", "t": "{{C}} I am not the patient, but I have obtained the patient’s express authorization."}, {"k": "p", "t": "{{C}} I am legally authorized to make the relevant decision on behalf of the patient."}, {"k": "p", "t": "Relationship of representative or lawful agent to the patient: {{B:28}}"}, {"k": "p", "t": "Authority or legal basis: {{B:28}}"}, {"k": "p", "t": "6. Applicable Cross-boundary Route"}, {"k": "h2", "t": "Select one only:"}, {"k": "h2", "t": "{{C}} Mainland China → Hong Kong"}, {"k": "h2", "t": "{{C}} Mainland China → Macao"}, {"k": "h2", "t": "{{C}} Hong Kong → Macao"}, {"k": "h2", "t": "{{C}} Macao → Hong Kong"}, {"k": "h2", "t": "{{C}} Hong Kong → Mainland China"}, {"k": "h2", "t": "{{C}} Macao → Mainland China"}, {"k": "p", "t": "7. Signature"}, {"k": "p", "t": "Patient signature: {{B:28}}"}, {"k": "p", "t": "Lawful representative or authorized agent signature, if applicable: {{B:28}}"}, {"k": "p", "t": "Date of signature: {{B:4}}/{{B:4}}/{{B:8}}"}, {"k": "p", "t": "Telephone: {{B:28}}"}, {"k": "p", "t": "Email address, if any: {{B:28}}"}, {"k": "p", "t": "Important notice: The six sets of route-specific provisions in this Agreement are alternative provisions. At the time of signature, only the set of Clauses 14 to 17 corresponding to the actual cross-boundary route should be retained or activated. The patient must not be asked to consent to all six routes at the same time."}], "pt": [{"k": "h1", "t": "Acordo de Transferência Transfronteiriça de Dados Pessoais e de Saúde"}, {"k": "p", "t": "Leia atentamente todas as cláusulas antes de assinar. O presente Acordo aplica-se apenas ao episódio actual de cuidados de saúde transfronteiriços e à transferência de dados expressamente identificada para esse episódio."}, {"k": "h2", "t": "Dados da autorização"}, {"k": "p", "t": "Nome do doente: {{B:28}}"}, {"k": "p", "t": "Representante e relação com o doente, se aplicável: {{B:28}}"}, {"k": "p", "t": "Entidade transmitente: {{B:28}}"}, {"k": "p", "t": "Instituição médica destinatária: {{B:28}}"}, {"k": "p", "t": "Rota transfronteiriça: {{B:28}}"}, {"k": "p", "t": "Finalidade dos cuidados: {{B:28}}"}, {"k": "p", "t": "Período da autorização: de {{B:4}}/{{B:4}}/{{B:8}} {{B:4}}:{{B:4}} a {{B:4}}/{{B:4}}/{{B:8}} {{B:4}}:{{B:4}}"}, {"k": "h2", "t": "Cláusulas gerais"}, {"k": "h3", "t": "Cláusula 1 | Serviço actual de cuidados de saúde transfronteiriços"}, {"k": "p", "t": "Está a solicitar um serviço transfronteiriço de marcação, referenciação, teleconsulta, diagnóstico, tratamento, consulta de seguimento, exame, análise laboratorial, verificação de receita, gestão de medicamentos ou devolução de registos clínicos. Para permitir que a instituição médica destinatária compreenda o seu estado de saúde e preste cuidados seguros e contínuos, os dados de identificação e de saúde indicados nesta página serão transferidos pela entidade transmitente para a instituição destinatária identificada. Esta autorização aplica-se apenas ao episódio de cuidados de saúde actualmente seleccionado."}, {"k": "h3", "t": "Cláusula 2 | Doente, representante e poderes de representação"}, {"k": "p", "t": "O doente em causa é a pessoa singular cujo nome, data de nascimento, tipo de documento e últimos quatro dígitos do número de documento são apresentados nesta página. O doente que actue pessoalmente deve concluir a verificação da identidade. O filho, cônjuge, tutor, cuidador ou representante deve verificar a sua identidade e confirmar que possui autorização válida ou poderes legais de representação."}, {"k": "h3", "t": "Cláusula 3 | Entidade transmitente e operador da plataforma"}, {"k": "p", "t": "A entidade transmitente é o hospital, clínica ou operador do sistema de registos de saúde cujo nome legal completo, endereço, licença, telefone e correio electrónico são apresentados nesta página. Caso o operador da plataforma participe na pesquisa, correspondência de identidade, conversão de formato, transmissão encriptada, armazenamento temporário ou gestão de registos de acesso, os seus dados de identificação e contacto também serão apresentados."}, {"k": "h3", "t": "Cláusula 4 | Instituição médica destinatária"}, {"k": "p", "t": "O destinatário limita-se à instituição médica identificada pelo nome legal completo nesta página. Serão igualmente apresentados o endereço, os dados de registo ou licença, o telefone, o correio electrónico, o serviço clínico e a equipa responsável. Sem nova autorização, os dados não serão comunicados a outra instituição não identificada nesta página."}, {"k": "h3", "t": "Cláusula 5 | Finalidades do tratamento e utilizações proibidas"}, {"k": "p", "t": "A instituição destinatária apenas poderá tratar os dados para verificar a identidade, realizar a marcação, triagem e referenciação, conhecer alergias, reacções adversas, antecedentes e medicação, apoiar o diagnóstico e tratamento, evitar exames repetidos ou prescrições incompatíveis, prestar serviços laboratoriais, imagiológicos, farmacêuticos e de enfermagem e constituir o registo clínico. Os dados não poderão ser utilizados para publicidade, marketing directo, promoção de seguros, definição de perfis comerciais, avaliação de crédito, treino de inteligência artificial não relacionado ou investigação médica não necessária."}, {"k": "h3", "t": "Cláusula 6 | Dados de identificação, marcação e cuidados"}, {"k": "p", "t": "Os dados de identificação e organização dos cuidados limitam-se ao nome, sexo, data de nascimento, documento de identificação, nacionalidade ou região, números de processo e consulta, telefone, endereço, contacto de emergência, cuidador ou representante, hospital, serviço, médico, data da consulta, razão da referenciação, sintomas preliminares, urgência e necessidades de acessibilidade. O sistema apresentará individualmente os elementos seleccionados."}, {"k": "h3", "t": "Cláusula 7 | Dados sensíveis de saúde e médicos"}, {"k": "p", "t": "Os dados sensíveis de saúde limitam-se aos elementos efectivamente seleccionados, incluindo queixa principal, doença actual, antecedentes, cirurgias, internamentos, história familiar, doenças infecciosas, alergias, reacções adversas, medicação, diagnósticos, receitas, processos clínicos, notas de alta, registos de enfermagem, ordens médicas, análises, patologia, vacinação, grupo sanguíneo, sinais vitais, reabilitação e imagens médicas, incluindo radiografia, tomografia computorizada, ressonância magnética, ecografia e endoscopia."}, {"k": "h3", "t": "Cláusula 8 | Método de transmissão e pessoal autorizado"}, {"k": "p", "t": "Os dados serão transmitidos por uma interface ou página encriptada e autenticada e não por correio electrónico comum, contas pessoais de mensagens, armazenamento público em nuvem ou dispositivos não autorizados. O acesso ficará limitado aos profissionais verificados que participem directamente nos cuidados e ao pessoal autorizado responsável pela gestão do processo clínico."}, {"k": "h3", "t": "Cláusula 9 | Prazo de acesso, conservação e eliminação"}, {"k": "p", "t": "O acesso em linha começa, em regra, sete dias antes da consulta e termina automaticamente 30 dias após o episódio de cuidados. A teleconsulta ou referenciação urgente poderá ser activada imediatamente após a autorização. Qualquer extensão exige nova informação e autorização. Ficheiros temporários e cópias intermédias serão apagados no prazo de 30 dias após o cumprimento da finalidade. Os processos clínicos legalmente constituídos serão conservados segundo as regras aplicáveis."}, {"k": "h3", "t": "Cláusula 10 | Medidas de segurança, tratamento por conta de outrem e comunicação ulterior"}, {"k": "p", "t": "As partes adoptarão encriptação, autenticação de dois factores, acesso segundo o menor privilégio, aprovação de acesso, registos, auditoria, alertas, protecção de cópias de segurança e resposta a incidentes. Apenas os dados necessários poderão ser comunicados a prestadores contratados de exames, imagiologia, farmácia, reabilitação ou manutenção, ficando estes sujeitos a contrato escrito."}, {"k": "h3", "t": "Cláusula 11 | Direitos do doente, retirada e reclamações"}, {"k": "p", "t": "O doente poderá consultar a entidade transmitente, o destinatário, a lista de dados, o prazo e o histórico de acessos e poderá impedir futuras transferências ainda não realizadas. Poderá solicitar acesso, rectificação ou complemento e apresentar reclamação por acesso não autorizado, tratamento excessivo ou violação de dados."}, {"k": "h3", "t": "Cláusula 12 | Incidentes de segurança de dados pessoais"}, {"k": "p", "t": "Em caso de fuga, alteração, perda, utilização ilícita ou acesso não autorizado, as instituições deverão conter o risco, limitar contas e acessos, preservar provas, avaliar o impacto e adoptar medidas correctivas. Quando exigida, a notificação ao doente indicará os dados envolvidos, a causa, os possíveis efeitos, as medidas tomadas, as medidas de protecção disponíveis e o contacto responsável."}, {"k": "h3", "t": "Cláusula 13 | Autorização prévia para acesso necessário em situação de emergência"}, {"k": "p", "t": "Dou o meu consentimento livre, expresso e separado para que, numa situação de emergência que ameace a minha vida ou saúde física, quando eu não possa manifestar atempadamente a minha vontade por inconsciência, incapacidade cognitiva, grave dificuldade de comunicação ou outra causa, a instituição médica responsável possa obter e utilizar directamente, no limite mínimo necessário à protecção da minha vida ou saúde: alergénios e reacções alérgicas conhecidos; reacções adversas graves a medicamentos; medicação crítica actual; antecedentes clínicos relevantes e cirurgias importantes; dispositivos médicos implantados; riscos de doenças transmissíveis; grupo sanguíneo; e outros dados que o médico responsável documente como indispensáveis ao tratamento urgente. Esta autorização não pode ser utilizada para cuidados de rotina, marketing, investigação, avaliação para seguros ou qualquer finalidade não urgente. Cada acesso de emergência deve registar o profissional, a hora, o motivo, o âmbito dos dados e o resultado. Terminada a emergência, a instituição deve informar-me, ou informar a pessoa legalmente habilitada a decidir por mim, logo que possível. Posso retirar esta autorização a qualquer momento, sem afectar o tratamento de dados legalmente realizado antes da retirada."}, {"k": "h2", "t": "Rota Um | China Continental → Hong Kong"}, {"k": "p", "t": "Aplicável apenas quando a rota transfronteiriça actual seja “China Continental → Hong Kong”."}, {"k": "h3", "t": "Cláusula 14 | Regime aplicável e mecanismo transfronteiriço"}, {"k": "p", "t": "A entidade transmitente encontra-se na China Continental e a destinatária em Hong Kong. A entidade transmitente deve cumprir os deveres de informação, informação específica sobre dados sensíveis, avaliação de impacto e transferência transfronteiriça previstos na Lei de Protecção de Informações Pessoais. A destinatária deve cumprir a Personal Data (Privacy) Ordinance de Hong Kong e os princípios aplicáveis de protecção de dados. Quando elegíveis, as partes podem utilizar o Contrato-Padrão da Grande Baía entre a China Continental e Hong Kong."}, {"k": "h3", "t": "Cláusula 15 | Regras de acesso após a recepção"}, {"k": "p", "t": "A instituição médica destinatária em Hong Kong apenas pode permitir o acesso a profissionais de saúde verificados que participem directamente nos cuidados actuais. Após cada acesso, o doente deve ser informado da instituição, hora do acesso, categorias de dados e departamento responsável."}, {"k": "h3", "t": "Cláusula 16 | Informação sobre diferenças jurídicas"}, {"k": "p", "t": "Hong Kong e a China Continental utilizam terminologia, autoridades reguladoras, procedimentos de reclamação e sistemas de registos clínicos diferentes. Os registos clínicos criados pela instituição destinatária em Hong Kong serão geridos de acordo com os requisitos aplicáveis em Hong Kong."}, {"k": "h3", "t": "Cláusula 17 | Consentimento final separado"}, {"k": "p", "t": "Confirmo que li todas as cláusulas e dou consentimento separado para a transferência dos dados pessoais e de saúde sensíveis indicados, da instituição médica identificada na China Continental para a instituição médica identificada em Hong Kong, exclusivamente para o presente episódio de cuidados transfronteiriços."}, {"k": "h2", "t": "Rota Dois | China Continental → Macau"}, {"k": "p", "t": "Aplicável apenas quando a rota transfronteiriça actual seja “China Continental → Macau”."}, {"k": "h3", "t": "Cláusula 14 | Regime aplicável e mecanismo transfronteiriço"}, {"k": "p", "t": "A entidade transmitente encontra-se na China Continental e o destinatário em Macau. A entidade transmitente cumprirá os deveres de informação, protecção de dados sensíveis, avaliação de impacto e transferência previstos na legislação da China Continental. A instituição médica de Macau, enquanto entidade responsável pelo tratamento, observará a Lei n.º 8/2005. Quando aplicável, as partes poderão utilizar o Contrato-Padrão da Grande Baía entre a China Continental e Macau."}, {"k": "h3", "t": "Cláusula 15 | Situação de conformidade da destinatária em Macau"}, {"k": "p", "t": "O sistema apresentará o contrato-padrão, a data de entrada em vigor, a data de registo e o respectivo estado. Quando sejam exigidas notificação, autorização para dados sensíveis ou outras formalidades, o respectivo estado será igualmente indicado. A transferência não terá início antes da obtenção de uma autorização prévia obrigatória."}, {"k": "h3", "t": "Cláusula 16 | Informação sobre diferenças jurídicas"}, {"k": "p", "t": "A legislação de Macau qualifica os dados de saúde como dados sensíveis. Existem diferenças quanto às autoridades, condições de tratamento, procedimentos de notificação ou autorização e direitos do titular."}, {"k": "h3", "t": "Cláusula 17 | Consentimento final separado"}, {"k": "p", "t": "Dou o meu consentimento livre, específico, informado e expresso para a transferência dos dados pessoais e de saúde sensíveis indicados, da instituição médica identificada na China Continental para a instituição médica identificada em Macau, exclusivamente para o presente episódio de cuidados."}, {"k": "h2", "t": "Rota Três | Hong Kong → Macau"}, {"k": "p", "t": "Aplicável apenas quando a rota transfronteiriça actual seja “Hong Kong → Macau”."}, {"k": "h3", "t": "Cláusula 14 | Regime aplicável"}, {"k": "p", "t": "O transmitente é um utilizador de dados de Hong Kong e o destinatário uma entidade responsável pelo tratamento em Macau. As partes deverão cumprir os respectivos regimes e celebrar um contrato escrito que regule as finalidades, categorias de dados, segurança, direitos, conservação e transferências subsequentes."}, {"k": "h3", "t": "Cláusula 15 | Avaliação de nova finalidade"}, {"k": "p", "t": "O sistema indicará se a transferência corresponde à finalidade original ou a uma finalidade directamente relacionada. Se constituir uma nova finalidade clínica, será obtido previamente o consentimento expresso, livre e informado."}, {"k": "h3", "t": "Cláusula 16 | Situação dos procedimentos em Macau"}, {"k": "p", "t": "O sistema apresentará o estado do registo, notificação ou autorização aplicável. O acesso não terá início enquanto uma autorização prévia obrigatória estiver pendente."}, {"k": "h3", "t": "Cláusula 17 | Consentimento final"}, {"k": "p", "t": "Dou o meu consentimento expresso, livre, específico e informado para a transferência dos dados indicados de Hong Kong para a instituição médica identificada em Macau."}, {"k": "h2", "t": "Rota Quatro | Macau → Hong Kong"}, {"k": "p", "t": "Aplicável apenas quando a rota transfronteiriça actual seja “Macau → Hong Kong”."}, {"k": "h3", "t": "Cláusula 14 | Regime aplicável"}, {"k": "p", "t": "O transmitente é uma entidade responsável pelo tratamento em Macau e o destinatário uma instituição médica de Hong Kong. O transmitente cumprirá a Lei n.º 8/2005 e determinará o fundamento e procedimento aplicáveis à transferência para fora de Macau, nomeadamente nos termos dos artigos 19.º e 20.º."}, {"k": "h3", "t": "Cláusula 15 | Procedimento de transferência para fora de Macau"}, {"k": "p", "t": "O sistema indicará se é aplicável o artigo 19.º ou o artigo 20.º e apresentará a data da notificação, a data do pedido de autorização, o número de referência e o estado actual. Quando seja exigida autorização prévia, não haverá transferência antes da respectiva concessão."}, {"k": "h3", "t": "Cláusula 16 | Restrições após a recepção em Hong Kong"}, {"k": "p", "t": "O destinatário em Hong Kong apenas poderá utilizar os dados para os cuidados actuais, não podendo utilizá-los para marketing directo ou novas finalidades não autorizadas."}, {"k": "h3", "t": "Cláusula 17 | Consentimento final"}, {"k": "p", "t": "Dou o meu consentimento livre, específico, informado e expresso para a transferência dos dados indicados da instituição médica identificada em Macau para a instituição médica identificada em Hong Kong."}, {"k": "p", "t": "Rota Cinco | Hong Kong → China Continental"}, {"k": "p", "t": "Aplicável apenas quando a rota transfronteiriça actual seja “Hong Kong → China Continental”."}, {"k": "h3", "t": "Cláusula 14 | Regime aplicável e contrato-padrão"}, {"k": "p", "t": "A entidade transmitente é um utilizador de dados de Hong Kong e a destinatária uma instituição médica da China Continental. A transmitente deve cumprir a Personal Data (Privacy) Ordinance de Hong Kong, e a instituição médica da China Continental deve tratar os dados nos termos da Lei de Protecção de Informações Pessoais. Quando aplicável, a transferência só pode ocorrer depois de o Contrato-Padrão da Grande Baía entrar em vigor e de ser concluído o registo exigido."}, {"k": "h3", "t": "Cláusula 15 | Regras de acesso da instituição destinatária"}, {"k": "p", "t": "A instituição médica destinatária na China Continental apenas pode permitir o acesso durante a marcação, consulta ou seguimento actual e somente a profissionais de saúde verificados que participem directamente nos cuidados. O doente deve ser informado após cada acesso."}, {"k": "h3", "t": "Cláusula 16 | Condutas proibidas à destinatária na China Continental"}, {"k": "p", "t": "A destinatária não pode exceder as finalidades e categorias de dados declaradas, nem utilizar os dados para publicidade farmacêutica, marketing de seguros, criação de perfis comerciais ou treino de inteligência artificial não relacionado. Qualquer alteração substancial exige nova avaliação de impacto, informação e consentimento aplicável."}, {"k": "h3", "t": "Cláusula 17 | Consentimento final"}, {"k": "p", "t": "Dou o meu consentimento expresso e voluntário para a transferência dos dados pessoais e de saúde sensíveis indicados, da entidade transmitente identificada em Hong Kong para a instituição médica identificada na China Continental, exclusivamente para os cuidados actuais."}, {"k": "h2", "t": "Rota Seis | Macau → China Continental"}, {"k": "p", "t": "Aplicável apenas quando a rota transfronteiriça actual seja “Macau → China Continental”."}, {"k": "h3", "t": "Cláusula 14 | Regime aplicável e contrato-padrão"}, {"k": "p", "t": "O transmitente é uma entidade responsável pelo tratamento em Macau e o destinatário uma instituição médica na China Continental. As partes cumprirão a Lei n.º 8/2005 e a Lei de Protecção de Informações Pessoais, respectivamente, podendo utilizar o Contrato-Padrão da Grande Baía quando aplicável."}, {"k": "h3", "t": "Cláusula 15 | Situação do contrato e registo"}, {"k": "p", "t": "O sistema apresentará o contrato-padrão, a data de entrada em vigor, a data de registo, a autoridade receptora e o estado actual. O registo aplicável deverá ser efectuado no prazo de dez dias úteis após a entrada em vigor. Não haverá transferência se o procedimento estiver incompleto, o contrato tiver caducado ou os dados excederem o âmbito registado."}, {"k": "h3", "t": "Cláusula 16 | Restrições à saída de Macau e à recepção na China Continental"}, {"k": "p", "t": "O transmitente em Macau cumprirá o procedimento aplicável. O hospital destinatário apenas tratará os dados para as finalidades, segundo os métodos e nas categorias previstos. Qualquer alteração exigirá nova avaliação e o cumprimento dos procedimentos correspondentes."}, {"k": "h3", "t": "Cláusula 17 | Consentimento final"}, {"k": "p", "t": "Dou o meu consentimento livre, específico, informado e expresso para a transferência dos dados pessoais e de saúde sensíveis indicados, da instituição médica identificada em Macau para a instituição médica identificada na China Continental, exclusivamente para o presente episódio de cuidados."}, {"k": "h2", "t": "Confirmação da assinatura"}, {"k": "p", "t": "1. Confirmação de leitura"}, {"k": "p", "t": "{{C}} Li e compreendi todas as cláusulas do presente Acordo."}, {"k": "p", "t": "2. Consentimento separado para a transferência transfronteiriça"}, {"k": "p", "t": "{{C}} Dou consentimento separado para esta transferência transfronteiriça de dados pessoais."}, {"k": "p", "t": "3. Consentimento separado para dados sensíveis de saúde e médicos"}, {"k": "p", "t": "{{C}} Dou consentimento separado para a transferência dos dados sensíveis de saúde e médicos identificados no presente Acordo."}, {"k": "p", "t": "4. Consentimento separado para acesso de emergência"}, {"k": "p", "t": "{{C}} Dou consentimento separado ao acesso, pela instituição médica responsável, no limite mínimo necessário, aos dados de saúde e médicos essenciais aos cuidados de emergência nas circunstâncias descritas no presente Acordo."}, {"k": "p", "t": "5. Confirmação dos poderes para assinar"}, {"k": "p", "t": "{{C}} Sou o doente."}, {"k": "p", "t": "{{C}} Não sou o doente, mas obtive a autorização expressa do doente."}, {"k": "p", "t": "{{C}} Estou legalmente habilitado a tomar a decisão relevante em nome do doente."}, {"k": "p", "t": "Relação do representante ou agente legal com o doente: {{B:28}}"}, {"k": "p", "t": "Poderes de representação ou fundamento legal: {{B:28}}"}, {"k": "p", "t": "6. Rota transfronteiriça aplicável"}, {"k": "h2", "t": "Seleccione apenas uma opção:"}, {"k": "h2", "t": "{{C}} China Continental → Hong Kong"}, {"k": "h2", "t": "{{C}} China Continental → Macau"}, {"k": "h2", "t": "{{C}} Hong Kong → Macau"}, {"k": "h2", "t": "{{C}} Macau → Hong Kong"}, {"k": "h2", "t": "{{C}} Hong Kong → China Continental"}, {"k": "h2", "t": "{{C}} Macau → China Continental"}, {"k": "p", "t": "7. Assinatura"}, {"k": "p", "t": "Assinatura do doente: {{B:28}}"}, {"k": "p", "t": "Assinatura do representante legal ou agente autorizado, se aplicável: {{B:28}}"}, {"k": "p", "t": "Data da assinatura: {{B:4}}/{{B:4}}/{{B:8}}"}, {"k": "p", "t": "Telefone: {{B:28}}"}, {"k": "p", "t": "Endereço de correio electrónico, se existente: {{B:28}}"}, {"k": "p", "t": "Aviso importante: Os seis conjuntos de cláusulas específicas por rota previstos no presente Acordo são alternativos. No momento da assinatura, deve ser mantido ou activado apenas o conjunto das Cláusulas 14 a 17 correspondente à rota transfronteiriça efectiva. Não deve ser solicitado ao doente que consinta simultaneamente em todas as seis rotas."}], "yue": [{"k": "h1", "t": "跨境就醫個人資料及健康醫療資料傳輸協議"}, {"k": "p", "t": "請在簽署前仔細閲讀以下全部條款。本協議只適用於本次跨境就醫及本次明確列明的資料傳輸。"}, {"k": "h2", "t": "本次授權資料"}, {"k": "p", "t": "病人姓名：{{B:28}}"}, {"k": "p", "t": "代辦人姓名及與病人的關係（如適用）：{{B:28}}"}, {"k": "p", "t": "資料提供方：{{B:28}}"}, {"k": "p", "t": "接收醫療機構：{{B:28}}"}, {"k": "p", "t": "跨境路徑：{{B:28}}"}, {"k": "p", "t": "本次診治目的：{{B:28}}"}, {"k": "p", "t": "授權有效期：由{{B:8}}年{{B:4}}月{{B:4}}日{{B:4}}時{{B:4}}分至{{B:8}}年{{B:4}}月{{B:4}}日{{B:4}}時{{B:4}}分"}, {"k": "h2", "t": "通用條款"}, {"k": "h2", "t": "第1條｜本次跨境醫療服務"}, {"k": "p", "t": "您正在申請跨境預約掛號、轉診、遠程會診、診斷、治療、複診、檢查檢驗、處方核驗、藥物管理或醫療紀錄回傳服務。"}, {"k": "p", "t": "為使接收醫療機構瞭解您的身體狀況並提供連續、安全的醫療服務，系統需要將本協議列明的身分資料和健康醫療資料，從本協議列明的資料提供方傳輸至本協議列明的接收醫療機構。"}, {"k": "p", "t": "本次授權只適用於本次就診申請，不構成對其他醫院、其他就診或未來醫療服務的長期授權。"}, {"k": "h2", "t": "第2條｜病人、代理者及代理資格"}, {"k": "p", "t": "本次資料所涉及的病人，是本協議“本次授權資料”部分列明的自然人。"}, {"k": "p", "t": "病人本人操作的，應完成實名身分核實；由子女、配偶、監護人、照顧者或其他代辦人操作的，代辦人應完成身分核實，並確認已經取得病人明確授權，或者依法具有代病人作出決定的資格。"}, {"k": "p", "t": "平台將保存授權關係、核驗結果及操作記錄。"}, {"k": "h2", "t": "第3條｜資料提供方及平台運營方"}, {"k": "p", "t": "本次資料提供方為本協議列明法定全稱的醫院、診所或電子健康紀錄系統運營機構。"}, {"k": "p", "t": "資料提供方應向病人提供其註冊地址、醫療機構執業許可證資料、聯繫電話和電郵地址。"}, {"k": "p", "t": "平台運營方如參與資料檢索、身分配對、格式轉換、加密傳輸、臨時緩存或存取日誌管理，應同時向病人提供平台運營方的法定全稱、註冊地址、統一社會信用代碼或商業登記資料、客服電話、電郵地址及個人資料保護負責人聯繫方式。"}, {"k": "h2", "t": "第4條｜接收醫療機構"}, {"k": "p", "t": "本次接收方僅為本協議列明法定全稱的醫療機構。"}, {"k": "p", "t": "接收醫療機構應向病人提供其註冊地址、醫療機構登記或許可資料、聯繫電話、電郵地址、接診科室及負責此次診治的醫護團隊資料。"}, {"k": "p", "t": "未經病人重新授權，資料不可提供給本協議未列明的其他醫院、診所、安老機構、藥房、保險公司、健康管理公司或商業機構。"}, {"k": "h2", "t": "第5條｜處理目的及禁止用途"}, {"k": "h2", "t": "接收醫療機構只可為以下目的處理資料："}, {"k": "p", "t": "核實病人身份；"}, {"k": "p", "t": "完成預約、分診和轉診；"}, {"k": "p", "t": "瞭解病人過敏紀錄、藥物不良反應、過往病歷和目前用藥；"}, {"k": "p", "t": "輔助醫生作出診斷、治療和複診決定；"}, {"k": "p", "t": "避免重複檢查、重複用藥和存在衝突的處方；"}, {"k": "p", "t": "提供檢驗、影像、藥事及護理服務；"}, {"k": "p", "t": "形成並向病人提供本次就診記錄。"}, {"k": "p", "t": "未經另行合法授權，不可將有關資料用於廣告、直接促銷、保險產品推介、商業畫像、信用評估、與本次診治無關的人工智能訓練、非必要醫學研究或其他不相容目的。"}, {"k": "h2", "t": "第6條｜身份、預約及照護資料"}, {"k": "h2", "t": "本次可能傳輸的身份及就醫安排資料僅包括："}, {"k": "p", "t": "病人姓名；"}, {"k": "p", "t": "性別；"}, {"k": "p", "t": "出生日期；"}, {"k": "p", "t": "證件類型及證件號碼；"}, {"k": "p", "t": "國籍或地區；"}, {"k": "p", "t": "病歷號及就診號；"}, {"k": "p", "t": "流動電話號碼及住址；"}, {"k": "p", "t": "緊急聯繫人；"}, {"k": "p", "t": "照顧者或代辦人的身分及關係；"}, {"k": "p", "t": "接收醫院；"}, {"k": "p", "t": "接診科室及接診醫生；"}, {"k": "p", "t": "預約日期；"}, {"k": "p", "t": "轉診原因；"}, {"k": "p", "t": "初步症狀及緊急程度；"}, {"k": "p", "t": "輪椅、陪診、傳譯、聽力、視力或其他無障礙服務需要。"}, {"k": "p", "t": "系統須逐項顯示本次實際傳輸的項目。未被勾選的項目不可傳輸。"}, {"k": "h2", "t": "第7條｜敏感健康醫療資料"}, {"k": "h2", "t": "本次涉及的健康醫療敏感個人資料包括系統實際勾選的下列項目："}, {"k": "p", "t": "主訴及現病歷；"}, {"k": "p", "t": "過往病歷；"}, {"k": "p", "t": "手術及住院紀錄；"}, {"k": "p", "t": "家族病歷；"}, {"k": "p", "t": "傳染病紀錄；"}, {"k": "p", "t": "過敏紀錄；"}, {"k": "p", "t": "藥物不良反應；"}, {"k": "p", "t": "目前及過往用藥；"}, {"k": "p", "t": "診斷結果；"}, {"k": "p", "t": "處方；"}, {"k": "p", "t": "門診及住院病歷；"}, {"k": "p", "t": "出院摘要；"}, {"k": "p", "t": "護理記錄及醫療指示；"}, {"k": "p", "t": "檢驗報告及病理報告；"}, {"k": "p", "t": "疫苗接種紀錄；"}, {"k": "p", "t": "血型；"}, {"k": "p", "t": "血壓、血糖、血氧及心率；"}, {"k": "p", "t": "復康紀錄；"}, {"k": "p", "t": "X光、CT、MRI、超聲、內窺鏡等醫學影像及相關報告。"}, {"k": "p", "t": "系統不可默認選擇全部病歷，只能選擇本次診治確有必要的資料項目。"}, {"k": "h2", "t": "第8條｜傳輸方式及存取人員"}, {"k": "p", "t": "資料應通過經身分認證的加密接口或加密網頁傳輸，不可通過普通電子郵件、個人即時通訊帳戶、公開網盤或未經批准的移動存儲設備發送。"}, {"k": "h2", "t": "資料傳輸至接收醫療機構後，僅限以下直接參與本次診治的實名人員存取："}, {"k": "p", "t": "註冊醫生；"}, {"k": "p", "t": "護士；"}, {"k": "p", "t": "藥師；"}, {"k": "p", "t": "化驗人員；"}, {"k": "p", "t": "醫學影像人員；"}, {"k": "p", "t": "復康人員；"}, {"k": "p", "t": "依法承擔病歷管理職責的授權人員。"}, {"k": "p", "t": "每次存取、下載、修改、打印或轉發均應記錄存取人員、存取時間、資料範圍、操作終端和處理目的。"}, {"k": "h2", "t": "第9條｜存取期限、保存期限及刪除"}, {"k": "p", "t": "接收醫療機構的在線查閲權限，原則上自預約日期前7日開始，並在本次就診結束後30日自動關閉。"}, {"k": "p", "t": "遠程會診或緊急轉診可在病人授權後即時開放。"}, {"k": "p", "t": "需要繼續複診或延長查閲期限的，應重新告知病人並取得授權。"}, {"k": "p", "t": "為跨境傳輸產生的臨時文件、緩存和中間副本，應在用途完成後30日內刪除。"}, {"k": "p", "t": "接收醫療機構依法形成的本地病歷，按照接收地醫療記錄保存規則保存，不因病人撤回跨境傳輸同意而當然刪除。"}, {"k": "h2", "t": "第10條｜安全措施、受託處理及再次提供"}, {"k": "h2", "t": "資料提供方、平台運營方和接收醫療機構應採取以下安全措施："}, {"k": "p", "t": "傳輸加密；"}, {"k": "p", "t": "存儲加密；"}, {"k": "p", "t": "雙重身分認證；"}, {"k": "p", "t": "最小權限控制；"}, {"k": "p", "t": "存取審批；"}, {"k": "p", "t": "操作紀錄；"}, {"k": "p", "t": "安全審計；"}, {"k": "p", "t": "異常存取警報；"}, {"k": "p", "t": "備份保護；"}, {"k": "p", "t": "安全事件響應。"}, {"k": "p", "t": "接收方只可將必要資料提供給為本次診治提供檢驗、影像、藥事、康復或系統維護服務的受託機構，並應通過書面合同限制受託機構的處理目的、資料範圍、保存期限和轉委託行為。"}, {"k": "p", "t": "未經新的合法依據，不可將資料繼續提供給其他司法管轄區或其他機構。"}, {"k": "h2", "t": "第11條｜病人權利、撤回及投訴"}, {"k": "p", "t": "病人可以查看資料提供方、接收醫療機構、資料清單、授權期限及存取記錄，並可以停止尚未發生的後續傳輸。"}, {"k": "p", "t": "病人有權申請查閲、更正或補充不準確的身分資料和醫療資料，並可就未經授權的存取、超範圍處理或資料外洩提出投訴。"}, {"k": "p", "t": "病人撤回同意，不影響撤回前已經完成的合法處理，也不要求醫療機構刪除依法必須保存的病歷。"}, {"k": "h2", "t": "第12條｜資料安全事件"}, {"k": "h2", "t": "發生或可能發生資料外洩、篡改、遺失、非法利用或未經授權存取時，相關機構應立即："}, {"k": "p", "t": "停止風險來源；"}, {"k": "p", "t": "限制相關帳戶和存取權限；"}, {"k": "p", "t": "保存有關證據；"}, {"k": "p", "t": "評估事件影響；"}, {"k": "p", "t": "採取補救措施。"}, {"k": "h2", "t": "依法需要通知病人時，通知應説明："}, {"k": "p", "t": "事件涉及的資料種類；"}, {"k": "p", "t": "事件發生原因；"}, {"k": "p", "t": "可能產生的影響；"}, {"k": "p", "t": "已經採取的補救措施；"}, {"k": "p", "t": "病人可以採取的保護措施；"}, {"k": "p", "t": "負責處理事件的聯繫人及聯繫方式。"}, {"k": "p", "t": "相關機構還應按照各自屬地適用的法律和監管要求向主管當局報告。"}, {"k": "h2", "t": "第13條｜緊急情況下的預先授權與必要資料存取"}, {"k": "p", "t": "本人自願、明確並單獨同意：當發生危及本人生命或身體健康的緊急情況，且本人因昏迷、認知障礙、嚴重溝通障礙或其他原因無法及時表達意願時，接診醫院可在保護本人生命健康所必需的最小範圍內，直接調取並使用以下資料："}, {"k": "p", "t": "已知過敏原及過敏反應；"}, {"k": "p", "t": "嚴重藥物不良反應；"}, {"k": "p", "t": "當前關鍵用藥；"}, {"k": "p", "t": "重要過往病歷；"}, {"k": "p", "t": "重大手術史；"}, {"k": "p", "t": "植入式醫療器械；"}, {"k": "p", "t": "傳染病風險；"}, {"k": "p", "t": "血型；"}, {"k": "p", "t": "由接診醫生書面判斷為緊急救治必須知悉的其他資料。"}, {"k": "p", "t": "該權限不可用於常規診治、營銷、研究、保險評估或其他非緊急目的。"}, {"k": "p", "t": "每次緊急存取均須記錄存取人員、存取時間、存取理由、資料範圍和處置結果。"}, {"k": "p", "t": "緊急情況消除後，醫院應儘快通知本人或依法有權代為決定的人。"}, {"k": "p", "t": "本授權可隨時撤回，但撤回不影響撤回前已經依法完成的緊急處理。"}, {"k": "h2", "t": "路徑一｜中國內地 → 香港"}, {"k": "p", "t": "僅在本次跨境路徑為“中國內地 → 香港”時適用。"}, {"k": "h2", "t": "第14條｜適用制度與跨境機制"}, {"k": "p", "t": "本次資料提供方位於中國內地，接收方位於香港特別行政區。"}, {"k": "p", "t": "資料提供方應依照《中華人民共和國個人資料保護法》，履行個人資料出境告知、敏感個人資料告知、個人資料保護影響評估及適用的跨境個人資料傳輸程序。"}, {"k": "p", "t": "接收方在香港處理資料時，應遵守香港《個人資料（私隱）條例》及適用的保障資料原則。"}, {"k": "p", "t": "雙方符合適用條件時，可採用粵港澳大灣區內地與香港個人資料跨境流動標準合同。"}, {"k": "h2", "t": "第15條｜接收後的存取安排"}, {"k": "p", "t": "香港接收醫院只能允許參與本次診治的實名醫護人員存取資料。"}, {"k": "h2", "t": "每次存取後，系統應向病人登記的流動電話號碼或電郵地址發出通知，載明："}, {"k": "p", "t": "醫院名稱；"}, {"k": "p", "t": "存取時間；"}, {"k": "p", "t": "資料類別；"}, {"k": "p", "t": "存取人員所屬科室。"}, {"k": "h2", "t": "第16條｜法律差異提示"}, {"k": "p", "t": "香港與中國內地在個人資料術語、監管機構、投訴程序和醫療記錄制度方面存在差異。"}, {"k": "p", "t": "資料進入香港後，由香港接收醫院形成的本地診治紀錄，將按照香港適用的法律及醫療記錄管理規則處理。"}, {"k": "h2", "t": "第17條｜最終單獨同意"}, {"k": "p", "t": "本人確認已閲讀並理解本協議全部條款，並單獨同意將本協議逐項列明的個人資料及健康醫療敏感個人資料，從本協議列明的中國內地醫療機構傳輸至本協議列明的香港醫療機構，僅用於本次跨境就醫。"}, {"k": "h2", "t": "路徑二｜中國內地 → 澳門"}, {"k": "p", "t": "僅在本次跨境路徑為“中國內地 → 澳門”時適用。"}, {"k": "h2", "t": "第14條｜適用制度與跨境機制"}, {"k": "p", "t": "本次資料提供方位於中國內地，接收方位於澳門特別行政區。"}, {"k": "p", "t": "資料提供方應依照《中華人民共和國個人資料保護法》，履行個人資料處理告知、敏感個人資料處理、個人資料保護影響評估及適用的數據出境程序。"}, {"k": "p", "t": "澳門接收醫療機構作為負責處理個人資料的實體，應遵守澳門第8/2005號法律《個人資料保護法》。"}, {"k": "p", "t": "符合適用條件時，雙方可採用粵港澳大灣區內地與澳門個人資料跨境流動標準合同。"}, {"k": "h2", "t": "第15條｜澳門接收方合規狀態"}, {"k": "h2", "t": "澳門接收醫療機構應向病人説明："}, {"k": "p", "t": "已簽署的標準合同名稱；"}, {"k": "p", "t": "合同生效日期；"}, {"k": "p", "t": "備案提交日期；"}, {"k": "p", "t": "備案接收機關；"}, {"k": "p", "t": "當前備案狀態；"}, {"k": "p", "t": "依法適用的自動化處理通知、敏感資料處理許可或其他程序的完成狀態。"}, {"k": "p", "t": "在依法需要事先許可，而有關許可尚未作出前，不可啓動資料傳輸。"}, {"k": "h2", "t": "第16條｜法律差異提示"}, {"k": "p", "t": "澳門法律將健康資料列為敏感資料。"}, {"k": "p", "t": "澳門與中國內地在主管當局、敏感資料處理條件、通知或許可程序以及資料當事人權利等方面存在差異。"}, {"k": "h2", "t": "第17條｜最終單獨同意"}, {"k": "p", "t": "本人確認已閲讀並理解本協議全部條款，並自由、具體、知情且明確地同意將本協議列明的個人資料及健康醫療敏感個人資料，從本協議列明的中國內地醫療機構傳輸至本協議列明的澳門醫療機構，僅用於本次跨境就醫。"}, {"k": "h2", "t": "路徑三｜香港 → 澳門"}, {"k": "p", "t": "僅在本次跨境路徑為“香港 → 澳門”時適用。"}, {"k": "h2", "t": "第14條｜適用制度"}, {"k": "p", "t": "本次資料提供方為香港的資料使用者，接收方為澳門負責處理個人資料的實體。"}, {"k": "p", "t": "香港資料提供方應遵守香港《個人資料（私隱）條例》及適用的保障資料原則；澳門接收方應遵守澳門第8/2005號法律《個人資料保護法》。"}, {"k": "p", "t": "本路徑不直接適用內地與香港或內地與澳門的大灣區個人資料跨境流動標準合同。"}, {"k": "h2", "t": "雙方應以書面跨境資料處理合同明確："}, {"k": "p", "t": "處理目的；"}, {"k": "p", "t": "資料範圍；"}, {"k": "p", "t": "安全措施；"}, {"k": "p", "t": "資料當事人權利響應機制；"}, {"k": "p", "t": "保存期限；"}, {"k": "p", "t": "再次轉移限制；"}, {"k": "p", "t": "資料安全事件的處理責任。"}, {"k": "h2", "t": "第15條｜新用途判斷"}, {"k": "p", "t": "資料提供方應明確説明本次資料轉移是否屬於原收集目的，或者是否屬於與原收集目的直接相關的用途。"}, {"k": "p", "t": "如本次轉移屬於新的診治用途，香港資料提供方應在傳輸前取得病人明確、自願且知情的訂明同意。"}, {"k": "h2", "t": "第16條｜澳門程序狀態"}, {"k": "p", "t": "澳門接收醫療機構應向病人説明本次敏感健康資料處理所適用的登記、通知或許可狀態。"}, {"k": "p", "t": "依法需要事先許可而尚未取得許可的，不可開放資料存取。"}, {"k": "h2", "t": "第17條｜最終同意"}, {"k": "p", "t": "本人明確、自願地同意將本協議逐項列明的個人資料及健康醫療敏感資料，從本協議列明的香港資料提供方傳輸至本協議列明的澳門醫療機構，僅用於本次跨境就醫。"}, {"k": "h2", "t": "路徑四｜澳門 → 香港"}, {"k": "p", "t": "僅在本次跨境路徑為“澳門 → 香港”時適用。"}, {"k": "h2", "t": "第14條｜適用制度"}, {"k": "p", "t": "本次資料提供方為澳門負責處理個人資料的實體，接收方為香港醫療機構。"}, {"k": "p", "t": "澳門資料提供方應遵守澳門第8/2005號法律《個人資料保護法》，並根據該法律第19條、第20條及其他適用規定，確定向澳門以外地區轉移個人資料的法律依據和適用程序。"}, {"k": "p", "t": "香港接收方應遵守香港《個人資料（私隱）條例》及適用的保障資料原則。"}, {"k": "h2", "t": "第15條｜澳門轉出程序"}, {"k": "h2", "t": "澳門資料提供方應向病人説明："}, {"k": "p", "t": "本次轉移適用澳門第8/2005號法律第19條或第20條的具體路徑；"}, {"k": "p", "t": "通知提交日期；"}, {"k": "p", "t": "許可申請日期；"}, {"k": "p", "t": "主管當局編號；"}, {"k": "p", "t": "當前程序狀態。"}, {"k": "p", "t": "依法需要事先取得許可的，在許可作出前不可傳輸資料。"}, {"k": "h2", "t": "第16條｜香港接收後的限制"}, {"k": "p", "t": "香港接收醫院只能將資料用於本次診治，不可將資料用於直接促銷或其他未經授權的新目的。"}, {"k": "p", "t": "需要將資料再次轉移至香港以外的地區或機構時，應重新進行評估、履行告知義務並取得適用的授權或同意。"}, {"k": "h2", "t": "第17條｜最終同意"}, {"k": "p", "t": "本人自由、具體、知情且明確地同意將本協議列明的個人資料及健康醫療敏感資料，從本協議列明的澳門醫療機構傳輸至本協議列明的香港醫療機構，僅用於本次跨境就醫。"}, {"k": "h2", "t": "路徑五｜香港 → 中國內地"}, {"k": "p", "t": "僅在本次跨境路徑為“香港 → 中國內地”時適用。"}, {"k": "h2", "t": "第14條｜適用制度與標準合同"}, {"k": "p", "t": "本次資料提供方為香港的資料使用者，接收方為中國內地醫療機構。"}, {"k": "p", "t": "香港資料提供方應遵守香港《個人資料（私隱）條例》及適用的保障資料原則；中國內地接收醫院應按照《中華人民共和國個人資料保護法》處理資料。"}, {"k": "p", "t": "雙方符合粵港澳大灣區內地與香港個人資料跨境流動標準合同適用條件時，應在標準合同生效並完成規定程序後開展資料傳輸。"}, {"k": "h2", "t": "第15條｜接收醫院存取規則"}, {"k": "p", "t": "中國內地接收醫院只能在病人本次就診、會診或複診期間，允許實名註冊並直接參與本次診治的醫護人員存取資料。"}, {"k": "h2", "t": "每次存取後，系統應向病人發出通知，並列明："}, {"k": "p", "t": "接收醫院；"}, {"k": "p", "t": "存取時間；"}, {"k": "p", "t": "存取資料的類別；"}, {"k": "p", "t": "存取人員所屬科室。"}, {"k": "h2", "t": "第16條｜內地接收方的禁止行為"}, {"k": "h2", "t": "中國內地接收醫院不可超出本協議列明的目的和資料種類處理相關資料，不可將資料用於："}, {"k": "p", "t": "藥品廣告；"}, {"k": "p", "t": "保險營銷；"}, {"k": "p", "t": "商業畫像；"}, {"k": "p", "t": "與本次診治無關的人工智能訓練；"}, {"k": "p", "t": "其他與本次診治目的不相容的用途。"}, {"k": "p", "t": "處理目的、處理方式、資料種類或保存期限發生實質變化時，應重新進行個人資料保護影響評估，並重新告知病人及取得適用的同意。"}, {"k": "h2", "t": "第17條｜最終同意"}, {"k": "p", "t": "本人明確、自願地同意將本協議列明的個人資料及健康醫療敏感資料，從本協議列明的香港資料提供方傳輸至本協議列明的中國內地醫療機構，僅用於本次跨境就醫。"}, {"k": "h2", "t": "路徑六｜澳門 → 中國內地"}, {"k": "p", "t": "僅在本次跨境路徑為“澳門 → 中國內地”時適用。"}, {"k": "h2", "t": "第14條｜適用制度與標準合同"}, {"k": "p", "t": "本次資料提供方為澳門負責處理個人資料的實體，接收方為中國內地醫療機構。"}, {"k": "p", "t": "澳門資料提供方應遵守澳門第8/2005號法律《個人資料保護法》；中國內地接收醫院應遵守《中華人民共和國個人資料保護法》。"}, {"k": "p", "t": "符合適用條件時，雙方可採用粵港澳大灣區內地與澳門個人資料跨境流動標準合同。"}, {"k": "h2", "t": "第15條｜合同及備案狀態"}, {"k": "h2", "t": "資料提供方和接收方應向病人説明："}, {"k": "p", "t": "雙方簽署的內地與澳門大灣區標準合同名稱；"}, {"k": "p", "t": "合同生效日期；"}, {"k": "p", "t": "備案提交日期；"}, {"k": "p", "t": "備案接收機關；"}, {"k": "p", "t": "當前備案狀態。"}, {"k": "p", "t": "程序尚未完成、合同已經失效或傳輸資料超出適用範圍時，不可啓動資料傳輸。"}, {"k": "h2", "t": "第16條｜澳門轉出及內地接收限制"}, {"k": "p", "t": "澳門資料提供方應完成適用的跨境轉移程序。"}, {"k": "p", "t": "中國內地接收醫院只能按照本協議及適用的標準合同所列明的目的、方式和資料類別處理有關資料。"}, {"k": "p", "t": "處理目的、資料範圍、處理方式或保存期限發生變化時，雙方應重新評估，並根據實際情況補充或重新訂立協議，履行相應的告知、同意及其他適用程序。"}, {"k": "h2", "t": "第17條｜最終同意"}, {"k": "p", "t": "本人自由、具體、知情且明確地同意將本協議列明的個人資料及健康醫療敏感資料，從本協議列明的澳門醫療機構傳輸至本協議列明的中國內地醫療機構，僅用於本次跨境就醫。"}, {"k": "h2", "t": "簽署確認"}, {"k": "h2", "t": "一、協議閲讀確認"}, {"k": "p", "t": "{{C}} 我已逐條閲讀並理解本協議。"}, {"k": "h2", "t": "二、跨境傳輸單獨同意"}, {"k": "p", "t": "{{C}} 我單獨同意本次個人資料跨境傳輸。"}, {"k": "h2", "t": "三、敏感健康醫療資料單獨同意"}, {"k": "p", "t": "{{C}} 我另行同意傳輸本協議列明的健康醫療敏感個人資料。"}, {"k": "h2", "t": "四、緊急存取單獨同意"}, {"k": "p", "t": "{{C}} 我單獨同意在本協議所述緊急情況下，由接診醫院按最小必要範圍存取救治所必需的健康醫療資料。"}, {"k": "h2", "t": "五、簽署資格確認"}, {"k": "p", "t": "{{C}} 我是病人本人。"}, {"k": "p", "t": "{{C}} 我不是病人本人，但已取得病人明確授權。"}, {"k": "p", "t": "{{C}} 我依法具有代病人作出相關決定的資格。"}, {"k": "p", "t": "代辦人或法定代理人與病人的關係：{{B:28}}"}, {"k": "p", "t": "代理權限或法律依據：{{B:28}}"}, {"k": "h2", "t": "六、實際適用的跨境路徑"}, {"k": "h2", "t": "請只勾選一項："}, {"k": "h2", "t": "{{C}} 中國內地 → 香港"}, {"k": "h2", "t": "{{C}} 中國內地 → 澳門"}, {"k": "h2", "t": "{{C}} 香港 → 澳門"}, {"k": "h2", "t": "{{C}} 澳門 → 香港"}, {"k": "h2", "t": "{{C}} 香港 → 中國內地"}, {"k": "h2", "t": "{{C}} 澳門 → 中國內地"}, {"k": "h2", "t": "七、簽名"}, {"k": "p", "t": "病人簽名：{{B:28}}"}, {"k": "p", "t": "法定代理人或獲授權代辦人簽名（如適用）：{{B:28}}"}, {"k": "p", "t": "簽署日期：{{B:8}}年{{B:4}}月{{B:4}}日"}, {"k": "p", "t": "聯繫電話：{{B:28}}"}, {"k": "p", "t": "電郵地址（如有）：{{B:28}}"}, {"k": "p", "t": "重要提示：本協議中的六組路徑特別條款屬於備選條款。實際簽署時，應只保留或啓用與本次跨境路徑對應的一組第14條至第17條，不應要求病人同時同意六條不同跨境路徑。"}]};
